mapper.select:
SELECT COUNT(*) > 0
FROM member
WHERE member_name = #{memberName}
  AND member_email = #{memberEmail}

SELECT member_id
FROM member
WHERE member_name = #{memberName}
  AND member_email = #{memberEmail}

SELECT COUNT(*) > 0
FROM member
WHERE member_id = #{memberId}
  AND member_email = #{memberEmail}

mapper.update:
UPDATE member
SET member_password = #{memberPassword}
WHERE member_id = #{memberId}

mapper.delete:
DELETE FROM member
WHERE member_status = 'DELETED'
  AND deleted_at <= #{cutoffDate}
